package calc

func loopsum(n int64) int64 {
	var s int64
	for i := int64(0); i < n; i++ {
		s = (s + i+i) % 1000000007
	}
	return s
}

package calc

import "testing"

func TestLoopsum(t *testing.T) {
	if got := loopsum(0); got != 0 {
		t.Errorf("loopsum(0) = %d, want 0", got)
	}
	if got := loopsum(10); got != 285 {
		t.Errorf("loopsum(10) = %d, want 285", got)
	}
	if got := loopsum(1000); got != 332833500 {
		t.Errorf("loopsum(1000) = %d, want 332833500", got)
	}
}
